// Real token validation for L1 notify (Phase 2B fix)
// Token from env credential, exact match only, reject missing/wrong, never log
const headers = $input.first().json.headers || $json.headers || {};
const body = $input.first().json.body || $json.body || $json;

const expected = ($env.N8N_WEBHOOK_TOKEN || $env.N8N_CALLBACK_TOKEN || '').trim();
if (!expected) {
  throw new Error('Server misconfigured: shared token not set in n8n env');
}
const authHeader = (headers['authorization'] || '').trim();
const bearer = authHeader.toLowerCase().startsWith('bearer ') ? authHeader.slice(7).trim() : '';
const supplied = (headers['x-n8n-token'] || headers['x-callback-token'] || bearer || '').trim();
if (!supplied) {
  throw new Error('Missing authentication token - X-N8N-Token required');
}
if (supplied !== expected) {
  throw new Error('Invalid authentication token');
}

// Ensure no full_log (defense in depth)
const payloadStr = JSON.stringify(body).toLowerCase();
if (payloadStr.includes('full_log')) {
  throw new Error('Security violation: payload must not contain full_log');
}

return { json: body.payload ? body.payload : body };

// Format L1 notification (no full_log, summary only)
const alert = $input.first().json;
const severity = (alert.severity || 'unknown').toUpperCase();
const score = alert.score ?? 'n/a';
const decision = alert.decision || {};
const rule = alert.rule || 'unknown';
const iocs = alert.iocs || {};
const links = alert.investigation_links || {};
const feedbackUrl = links.feedback_url || `${$env.TRIAGE_API_BASE_URL || 'http://triage-api:8000'}/api/v1/alerts/${alert.alert_id}/feedback`;

const subject = `[SOC][${severity}] Alert ${alert.alert_id} - ${decision.severity || rule}`;

const bodyText = `
SOC Alert - L1 Review
--------------------
Alert ID: ${alert.alert_id}
Severity: ${severity}
Score: ${score}
Decision: ${decision.severity || 'unknown'} / ${decision.action || ''}
Rule: ${rule}
Recurrence: ${alert.recurrence || 'unknown'}

IOCs:
- IPs: ${(iocs.ips || []).join(', ') || 'none'}
- Domains: ${(iocs.domains || []).join(', ') || 'none'}
- Hashes: ${(iocs.hashes || []).join(', ') || 'none'}
- Users: ${(iocs.users || []).join(', ') || 'none'}

Enrichment: ${JSON.stringify(alert.enrichment || {}).slice(0, 500)}

Investigation:
- SIEM: ${links.siem_search_url || 'n/a'}
- Timeline: ${links.timeline_url || 'n/a'}
- Feedback: ${feedbackUrl}

Note: contain_requested creates an approval-required request; no containment action is executed. Human approval required.
No autonomous response.
`;

return {
  json: {
    alert_id: alert.alert_id,
    severity: alert.severity,
    subject,
    bodyText,
    feedbackUrl,
    _notify: {
      formatted_at: new Date().toISOString()
    }
  }
};
